import React, { useState, useEffect, useCallback } from 'react';
import { format } from 'date-fns';
import { useAuth } from '../context/AuthContext';
import webSocketService from '../services/websocketService';

const NewsCard = ({ article, showCategory = false, isBreaking = false }) => {
  const { user } = useAuth();
  const [reactions, setReactions] = useState({
    like: 0,
    angry: 0,
    sad: 0,
    support: 0
  });
  const [userReaction, setUserReaction] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const [showComments, setShowComments] = useState(false);
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState('');

  const {
    id,
    title,
    description,
    urlToImage,
    publishedAt,
    source,
    url,
    category
  } = article;

  // Initialize WebSocket connection
  useEffect(() => {
    if (user?.token) {
      webSocketService.connect(user.token);
      setIsConnected(true);
      
      return () => {
        webSocketService.disconnect();
        setIsConnected(false);
      };
    }
  }, [user]);

  // Subscribe to article updates
  useEffect(() => {
    if (!isConnected || !id) return;

    // Subscribe to the article
    webSocketService.subscribeToArticle(id);

    // Set up reaction update listener
    const unsubscribeReaction = webSocketService.onReactionUpdate(
      id,
      (data) => {
        setReactions(prev => ({
          ...prev,
          [data.type]: data.count || 0
        }));
        
        if (data.userId === user?.id) {
          setUserReaction(data.type);
        }
      }
    );

    // Set up new comment listener
    const unsubscribeComment = webSocketService.onNewComment(
      id,
      (comment) => {
        setComments(prev => [...prev, comment]);
      }
    );

    // Initial load of reactions and comments
    const loadInitialData = async () => {
      try {
        // TODO: Replace with actual API call to get initial reactions and comments
        // const response = await api.get(`/api/news/${id}/reactions`);
        // setReactions(response.data.reactions);
        // setUserReaction(response.data.userReaction);
        // setComments(response.data.comments || []);
      } catch (error) {
        console.error('Error loading initial data:', error);
      }
    };

    loadInitialData();

    return () => {
      unsubscribeReaction();
      unsubscribeComment();
    };
  }, [id, isConnected, user?.id]);

  const handleReaction = useCallback((type) => {
    if (!user) return;
    
    const isSameReaction = userReaction === type;
    const newType = isSameReaction ? null : type;
    
    // Optimistic update
    setReactions(prev => {
      const newReactions = { ...prev };
      
      // Remove previous reaction if exists
      if (userReaction) {
        newReactions[userReaction] = Math.max(0, newReactions[userReaction] - 1);
      }
      
      // Add new reaction if not toggling off
      if (newType) {
        newReactions[newType] = (newReactions[newType] || 0) + 1;
      }
      
      return newReactions;
    });
    
    const previousReaction = userReaction;
    setUserReaction(newType);
    
    // Send reaction to server
    webSocketService.sendReaction(id, newType);
    
    // Revert on error
    const handleError = () => {
      setUserReaction(previousReaction);
      // Revert reactions state
      setReactions(prev => {
        const reverted = { ...prev };
        if (previousReaction) reverted[previousReaction] = (reverted[previousReaction] || 0) + 1;
        if (newType) reverted[newType] = Math.max(0, (reverted[newType] || 0) - 1);
        return reverted;
      });
    };
    
    // Simulate error handling (replace with actual API call if needed)
    setTimeout(() => {
      if (!isConnected) {
        handleError();
      }
    }, 5000);
    
  }, [user, userReaction, id, isConnected]);

  const handleCommentSubmit = (e) => {
    e.preventDefault();
    if (!newComment.trim() || !user) return;
    
    const comment = {
      id: Date.now().toString(),
      content: newComment,
      userId: user.id,
      username: user.username,
      timestamp: new Date().toISOString()
    };
    
    // Optimistic update
    setComments(prev => [...prev, comment]);
    setNewComment('');
    
    // Send comment to server
    webSocketService.sendComment(id, newComment);
  };

  const formatDate = (dateString) => {
    try {
      return format(new Date(dateString), 'MMM d, yyyy');
    } catch (e) {
      return '';
    }
  };

  return (
    <div className={`rounded-lg overflow-hidden shadow-md hover:shadow-lg transition-shadow duration-300 bg-white ${isBreaking ? 'border-l-4 border-red-500' : ''}`}>
      {isBreaking && (
        <div className="bg-red-100 text-red-800 px-4 py-1 text-sm font-medium">
          BREAKING
        </div>
      )}
      
      <div className="relative h-48 overflow-hidden">
        {urlToImage ? (
          <img
            src={urlToImage}
            alt={title}
            className="w-full h-full object-cover hover:scale-105 transition-transform duration-300"
            onError={(e) => {
              e.target.onerror = null;
              e.target.src = 'https://via.placeholder.com/400x200?text=No+Image+Available';
            }}
          />
        ) : (
          <div className="w-full h-full bg-gray-200 flex items-center justify-center">
            <span className="text-gray-400">No Image Available</span>
          </div>
        )}
        {showCategory && category && (
          <span className="absolute top-2 right-2 bg-blue-500 text-white text-xs px-2 py-1 rounded-full">
            {category.charAt(0).toUpperCase() + category.slice(1)}
          </span>
        )}
      </div>
      
      <div className="p-4">
        <div className="flex justify-between items-center mb-2">
          <span className="text-sm text-gray-500">
            {source?.name || 'Unknown Source'}
          </span>
          <span className="text-sm text-gray-400">
            {formatDate(publishedAt)}
          </span>
        </div>
        
        <h3 className="text-lg font-semibold mb-2 line-clamp-2">
          {title}
        </h3>
        
        <p className="text-gray-600 text-sm mb-4 line-clamp-3">
          {description || 'No description available.'}
        </p>
        
        <div className="flex justify-between items-center">
          <a
            href={url}
            target="_blank"
            rel="noopener noreferrer"
            className="text-blue-500 hover:text-blue-700 text-sm font-medium"
          >
            Read More →
          </a>
          <div className="flex space-x-2">
            <button className="text-gray-400 hover:text-red-500">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
              </svg>
            </button>
            <button className="text-gray-400 hover:text-blue-500">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
              </svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NewsCard;
